import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline
cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride_h, int stride_w,
                                   int pad_h, int pad_w,
                                   int dil_h, int dil_w);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T, int TILE_H, int TILE_W, int CoPerBlock>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  // CTA-level 2D output-spatial tiling with shared-memory staging of the
  // reusable input tile. Neighboring output pixels within a tile share
  // overlapping receptive fields, so the input patch is loaded once into
  // shared memory (with zero-fill for padding) and reused by all threads
  // in the block across the Cin/Kh/Kw reduction and across CoPerBlock
  // output channels, instead of each thread re-reading global memory.
  constexpr int Threads    = TILE_H * TILE_W;
  const int tid = threadIdx.x;
  const int local_oh = tid / TILE_W;
  const int local_ow = tid % TILE_W;
  const int n = blockIdx.z;
  const int CoTiles = (Cout + CoPerBlock - 1) / CoPerBlock;
  const int ow_tile = blockIdx.x;
  const int oh_tile = blockIdx.y;
  const int oh_base = oh_tile * TILE_H;
  const int ow_base = ow_tile * TILE_W;
  const int IH_TILE = (TILE_H - 1) * stride_h + dil_h * (Kh - 1) + 1;
  const int IW_TILE = (TILE_W - 1) * stride_w + dil_w * (Kw - 1) + 1;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, Kh, Kw),
      make_stride((int64_t)Cin * Kh * Kw, (int64_t)Kh * Kw, (int64_t)Kw, (int64_t)1));
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  const int64_t per_co_elems = (int64_t)Cin * Kh * Kw;
  T* sX_ptr = sW_ptr + CoPerBlock * per_co_elems;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(CoPerBlock, Cin, Kh, Kw),
      make_stride(per_co_elems, (int64_t)Kh * Kw, (int64_t)Kw, (int64_t)1));
  const int64_t per_ci_elems = (int64_t)IH_TILE * IW_TILE;
  // Cooperative load of the reusable input tile into shared memory,
  // zero-filled for out-of-bounds (padding) positions. Loaded once per
  // CTA and reused across every output-channel tile processed below,
  // eliminating redundant re-fetching of the same input patch from
  // global memory for each output-channel chunk.
  const int base_ih_global = oh_base * stride_h - pad_h;
  const int base_iw_global = ow_base * stride_w - pad_w;
  const int64_t total_x_elems = (int64_t)Cin * per_ci_elems;
  for (int64_t idx = tid; idx < total_x_elems; idx += Threads) {
    int64_t ci = idx / per_ci_elems;
    int64_t rem = idx % per_ci_elems;
    int64_t ih_local = rem / IW_TILE;
    int64_t iw_local = rem % IW_TILE;
    int ih = base_ih_global + (int)ih_local;
    int iw = base_iw_global + (int)iw_local;
    T val = T(0);
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      val = mX((int)ci, ih, iw);
    }
    sX_ptr[ci * per_ci_elems + rem] = val;
  }
  __syncthreads();
  const int oh = oh_base + local_oh;
  const int ow = ow_base + local_ow;
  const bool valid = (oh < Hout) && (ow < Wout);
  for (int co_tile = 0; co_tile < CoTiles; ++co_tile) {
    const int co_base = co_tile * CoPerBlock;
    // Cooperative load of this output-channel chunk's weights into shared
    // memory. The weight buffer is reused across iterations while the
    // input tile above stays resident for the whole loop.
    for (int co = 0; co < CoPerBlock; ++co) {
      int co_global = co_base + co;
      for (int64_t idx = tid; idx < per_co_elems; idx += Threads) {
        T val = T(0);
        if (co_global < Cout) {
          int64_t ci = idx / (Kh * Kw);
          int64_t rem = idx % (Kh * Kw);
          int64_t kh = rem / Kw;
          int64_t kw = rem % Kw;
          val = mW(co_global, (int)ci, (int)kh, (int)kw);
        }
        sW_ptr[co * per_co_elems + idx] = val;
      }
    }
    __syncthreads();
    float acc[CoPerBlock];
    #pragma unroll
    for (int co = 0; co < CoPerBlock; ++co) acc[co] = 0.0f;
    if (valid) {
      for (int kh = 0; kh < Kh; ++kh) {
        int ih_local = local_oh * stride_h + kh * dil_h;
        for (int kw = 0; kw < Kw; ++kw) {
          int iw_local = local_ow * stride_w + kw * dil_w;
          const T* sX_row = sX_ptr + ih_local * IW_TILE + iw_local;
          for (int ci = 0; ci < Cin; ++ci) {
            float xval = (float)sX_row[ci * per_ci_elems];
            #pragma unroll
            for (int co = 0; co < CoPerBlock; ++co) {
              float wval = (float)sW(co, ci, kh, kw);
              acc[co] += xval * wval;
            }
          }
        }
      }
    }
    if (valid) {
      #pragma unroll
      for (int co = 0; co < CoPerBlock; ++co) {
        int co_global = co_base + co;
        if (co_global >= Cout) continue;
        float bval = 0.0f;
        if (Bias != nullptr) {
          bval = (float)Bias[co_global];
        }
        mY(co_global, oh, ow) = static_cast<T>(acc[co] + bval);
      }
    }
    __syncthreads();
  }
}
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride_h, int stride_w,
                                   int pad_h, int pad_w,
                                   int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  int device = -1;
  cudaGetDevice(&device);
  int max_optin_smem = 0;
  cudaDeviceGetAttribute(&max_optin_smem,
      cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  int sm_shared_mem_per_sm = 0;
  cudaDeviceGetAttribute(&sm_shared_mem_per_sm,
      cudaDevAttrMaxSharedMemoryPerMultiprocessor, device);
  // Cap the per-block shared-memory footprint so multiple CTAs can reside
  // concurrently on each SM. Greedily maximizing tile size/smem usage (as
  // before) collapses occupancy to a single resident block per SM
  // (theoretical occupancy ~8%), starving warp schedulers and hiding no
  // latency. Targeting a fixed number of concurrent blocks per SM keeps
  // enough warps in flight to overlap load/compute/store stages.
  const int kTargetBlocksPerSM = 2;
  size_t smem_budget = (sm_shared_mem_per_sm > 0)
      ? (size_t)sm_shared_mem_per_sm / kTargetBlocksPerSM
      : (size_t)max_optin_smem;
  if (smem_budget > (size_t)max_optin_smem) smem_budget = (size_t)max_optin_smem;
  struct TileCand { int th; int tw; };
  const TileCand tile_candidates[] = {
      {16, 16}, {16, 8}, {8, 16}, {8, 8}, {8, 4}, {4, 8}, {4, 4}
  };
  const int candidate_co_per_block[] = {16, 8, 4, 2, 1};
  int chosen_tile_h = 0, chosen_tile_w = 0, chosen_co_per_block = 0;
  size_t smem_bytes = 0;
  for (const auto& tc : tile_candidates) {
    int ih_tile = (int)((tc.th - 1) * stride_h + dil_h * (Kh - 1) + 1);
    int iw_tile = (int)((tc.tw - 1) * stride_w + dil_w * (Kw - 1) + 1);
    size_t input_smem = (size_t)Cin * (size_t)ih_tile * (size_t)iw_tile * sizeof(float);
    if (input_smem > smem_budget) continue;
    for (int cand : candidate_co_per_block) {
      size_t weight_smem = (size_t)cand * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float);
      size_t total = weight_smem + input_smem;
      if (smem_budget >= total) {
        chosen_tile_h = tc.th;
        chosen_tile_w = tc.tw;
        chosen_co_per_block = cand;
        smem_bytes = total;
        break;
      }
    }
    if (chosen_co_per_block != 0) break;
  }
  if (chosen_co_per_block == 0) {
    // Fall back to the full opt-in shared-memory budget if no configuration
    // fits within the occupancy-friendly budget above (e.g. very large
    // Cin/Kh/Kw), preserving correctness at the cost of occupancy.
    for (const auto& tc : tile_candidates) {
      int ih_tile = (int)((tc.th - 1) * stride_h + dil_h * (Kh - 1) + 1);
      int iw_tile = (int)((tc.tw - 1) * stride_w + dil_w * (Kw - 1) + 1);
      size_t input_smem = (size_t)Cin * (size_t)ih_tile * (size_t)iw_tile * sizeof(float);
      if (input_smem > (size_t)max_optin_smem) continue;
      for (int cand : candidate_co_per_block) {
        size_t weight_smem = (size_t)cand * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float);
        size_t total = weight_smem + input_smem;
        if ((size_t)max_optin_smem >= total) {
          chosen_tile_h = tc.th;
          chosen_tile_w = tc.tw;
          chosen_co_per_block = cand;
          smem_bytes = total;
          break;
        }
      }
      if (chosen_co_per_block != 0) break;
    }
  }
  TORCH_CHECK(chosen_co_per_block != 0 && chosen_tile_h != 0 && chosen_tile_w != 0,
      "Required shared memory exceeds device max opt-in shared memory per block "
      "(", max_optin_smem, " B) even with the smallest tile/CoPerBlock configuration.");
  const int64_t WoutTiles = (Wout + chosen_tile_w - 1) / chosen_tile_w;
  const int64_t HoutTiles = (Hout + chosen_tile_h - 1) / chosen_tile_h;
  dim3 grid(
      (unsigned)WoutTiles,
      (unsigned)HoutTiles,
      (unsigned)N
  );
#define LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, COPB)                                    \
  do {                                                                              \
    dim3 block(TH * TW);                                                           \
    if (smem_bytes > 48 * 1024) {                                                  \
      auto attr_err = cudaFuncSetAttribute(conv2d_cute_kernel<float, TH, TW, COPB>, \
                            cudaFuncAttributeMaxDynamicSharedMemorySize,            \
                            (int)smem_bytes);                                       \
      TORCH_CHECK(attr_err == cudaSuccess,                                         \
          "Failed to opt-in to ", smem_bytes, " bytes of dynamic shared memory: ", \
          cudaGetErrorString(attr_err));                                           \
    }                                                                               \
    conv2d_cute_kernel<float, TH, TW, COPB><<<grid, block, smem_bytes, stream>>>(   \
        x_c.data_ptr<float>(),                                                     \
        w_c.data_ptr<float>(),                                                     \
        b_ptr,                                                                     \
        y.data_ptr<float>(),                                                       \
        (int)N, (int)Cin, (int)H, (int)Win,                                        \
        (int)Cout, (int)Kh, (int)Kw,                                               \
        stride_h, stride_w,                                                        \
        pad_h, pad_w,                                                              \
        dil_h, dil_w,                                                              \
        (int)Hout, (int)Wout                                                       \
    );                                                                             \
  } while (0)
#define DISPATCH_COPB(TH, TW)                                                                \
  do {                                                                                        \
    switch (chosen_co_per_block) {                                                            \
      case 16: LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, 16); break;                                  \
      case 8:  LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, 8);  break;                                  \
      case 4:  LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, 4);  break;                                  \
      case 2:  LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, 2);  break;                                  \
      case 1:  LAUNCH_CONV2D_CUTE_KERNEL(TH, TW, 1);  break;                                  \
      default:                                                                                \
        TORCH_CHECK(false, "Unsupported CoPerBlock selection: ", chosen_co_per_block);        \
    }                                                                                          \
  } while (0)
  const int tile_key = chosen_tile_h * 100 + chosen_tile_w;
  switch (tile_key) {
    case 1616: DISPATCH_COPB(16, 16); break;
    case 1608: DISPATCH_COPB(16, 8);  break;
    case 816:  DISPATCH_COPB(8, 16);  break;
    case 808:  DISPATCH_COPB(8, 8);   break;
    case 804:  DISPATCH_COPB(8, 4);   break;
    case 408:  DISPATCH_COPB(4, 8);   break;
    case 404:  DISPATCH_COPB(4, 4);   break;
    default:
      TORCH_CHECK(false, "Unsupported tile geometry selection: ", chosen_tile_h, "x", chosen_tile_w);
  }
#undef DISPATCH_COPB
#undef LAUNCH_CONV2D_CUTE_KERNEL
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""
conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input, asymmetric kernel, dilation and padding,
    implemented with a single custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        Kh, Kw = kernel_size
        ph, pw = padding
        dh, dw = dilation
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(Kh), int(Kw))
        self.stride_h = int(stride)
        self.stride_w = int(stride)
        self.pad_h = int(ph)
        self.pad_w = int(pw)
        self.dil_h = int(dh)
        self.dil_w = int(dw)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()
        self._ext = conv2d_ext
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride_h, self.stride_w,
            self.pad_h, self.pad_w,
            self.dil_h, self.dil_w,
        )

